  if(eb.x<ballR||eb.x>W-ballR)eb.dx=-eb.dx;
  if(eb.y<ballR)eb.dy=Math.abs(eb.dy);
  // Paddle bounce for extra balls
  if(eb.dy>0&&eb.y+ballR>=py&&eb.y+ballR<=py+paddleH+4&&eb.x>=px-4&&eb.x<=px+paddleW+4){
    let hit=(eb.x-(px+paddleW/2))/(paddleW/2);
    let spd=Math.sqrt(eb.dx*eb.dx+eb.dy*eb.dy);
    let angle=hit*Math.PI/4;
    eb.dx=spd*Math.sin(angle);eb.dy=-spd*Math.cos(angle);
    if(Math.abs(eb.dy)<spd*0.3){eb.dy=-spd*0.3;eb.dx=eb.dx>0?Math.sqrt(spd*spd-eb.dy*eb.dy):-Math.sqrt(spd*spd-eb.dy*eb.dy)}
